Lesson: What is an LLM?
Topic: Introduction to AI

## 6. Production Implementation Code

Below is production-ready code demonstrating What is an LLM?:




      java


      Copy Code


  import { GoogleGenAI } from &#x27;@google/genai&#x27;;

export class QAInferenceEngine {
  private ai: GoogleGenAI;
  private modelName = &#x27;gemini-2.5-flash&#x27;;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  async predictLocator(domSnapshot: string, targetDescription: string): Promise<string> {
    const prompt = `Given this HTML snippet:
${domSnapshot}
Return the most resilient CSS selector for: &quot;${targetDescription}&quot;. Respond in JSON: {&quot;selector&quot;: &quot;...&quot;, &quot;confidence&quot;: 0.0-1.0}`;
    try {
      const response = await this.ai.models.generateContent({
        model: this.modelName,
        contents: prompt,
        config: { temperature: 0.1, responseMimeType: &#x27;application/json&#x27; }
      });
      return response.text || &#x27;&#x27;;
    } catch (err: any) {
      if (err.message?.includes(&#x27;ContextWindowExceededError&#x27;)) {
        throw new Error(&#x27;DOM snapshot exceeded model token budget. Prune irrelevant nodes before retry.&#x27;);
      }
      throw err;
    }
  }
}

