Topic: Introduction to Playwright

## 5. Production Implementation Code

e2e-enterprise.spec.ts (typescript)

  import { test, expect } from &#039;@playwright/test&#039;;

test.describe(&#039;Enterprise Playwright Order Flow&#039;, () => {
  test(&#039;completes checkout with network mocking and state verification&#039;, async ({ page }) => {
    // 1. Mock external payment gateway
    await page.route(&#039;**/api/v1/payments&#039;, async (route) => {
      await route.fulfill({
        status: 200,
        contentType: &#039;application/json&#039;,
        body: JSON.stringify({ status: &#039;APPROVED&#039;, transactionId: &#039;TXN-9988-OK&#039; }),
      });
    });

    // 2. Navigate and leverage locator-first queries
    await page.goto(&#039;/catalog&#039;);
    await page.getByRole(&#039;button&#039;, { name: &#039;Add to Cart&#039; }).first().click();

    // 3. Auto-waiting handles modal opening without arbitrary sleeps
    await page.getByRole(&#039;link&#039;, { name: &#039;Cart&#039; }).click();
    await page.getByRole(&#039;button&#039;, { name: &#039;Confirm Purchase&#039; }).click();

    // 4. Web-first assertion auto-retries until condition succeeds
    await expect(page.getByTestId(&#039;confirmation-banner&#039;)).toHaveText(/Order #.*Placed Successfully/);
  });
});

Features network route interception, getByRole locators, auto-waiting actions, and web-first regex assertions.

